import{_ as t,c as s,o as e,b0 as n}from"./chunks/framework.C5ev1SXp.js";const i="/scm-docs/assets/iap-frame.Dh9tpaLB.svg",k=JSON.parse('{"title":"LV030-网络升级帧协议与三条通道","description":null,"frontmatter":{"title":"LV030-网络升级帧协议与三条通道","date":"2026-10-14T21:35:41.000Z","icon":"famicons:logo-markdown","permalink":"/sdoc/advanced-chapter/ethernet/126d628e13a52a7c8f19d4b3","index":true,"tags":null,"categories":null,"copyright":false,"keywords":null,"cover":null,"comments":null,"mathjax":null,"top":null,"description":null,"tdoc":{"detailDate":"2026-10-14T21:35:41.655Z","fulluuid":"2a7c8f19d4b341e5a86c02fd7b931e5c","useduuid":"2a7c8f19d"}},"headers":[],"relativePath":"sdoc/advanced-chapter/ethernet/126d628e13a52a7c8f19d4b3.md","filePath":"sdoc/30-进阶篇/06-以太网/LV030-网络升级帧协议与三条通道.md","lastUpdated":1792231946000}'),d={name:"sdoc/advanced-chapter/ethernet/126d628e13a52a7c8f19d4b3.md"};function r(o,a,l,p,c,h){return e(),s("div",null,[...a[0]||(a[0]=[n(`<h1 id="lv030-网络升级帧协议与三条通道" tabindex="-1">LV030-网络升级帧协议与三条通道 <a class="header-anchor" href="#lv030-网络升级帧协议与三条通道" aria-label="Permalink to &quot;LV030-网络升级帧协议与三条通道&quot;">​</a></h1><blockquote><p><strong>前置阅读</strong>：<a href="/scm-docs/sdoc/advanced-chapter/ethernet/126d628e13a5205f2a80bf1e.html">LV020-网络通信实验</a> 用 TCP 通道、<a href="/scm-docs/sdoc/advanced-chapter/ethernet/126d628e13a5261051823e07.html">LV025-基于TFTP的网络升级实验</a> 用 TFTP 通道，两条通道都&quot;发完即止&quot;。本篇把两条通道下面共同的那一层——<strong>固件帧协议与收帧状态机</strong>——单独讲透。</p></blockquote><h2 id="一、-为什么三条通道要共用一套帧格式" tabindex="-1">一、 为什么三条通道要共用一套帧格式 <a class="header-anchor" href="#一、-为什么三条通道要共用一套帧格式" aria-label="Permalink to &quot;一、 为什么三条通道要共用一套帧格式&quot;">​</a></h2><h3 id="_1-三条通道分别是什么" tabindex="-1">1. 三条通道分别是什么 <a class="header-anchor" href="#_1-三条通道分别是什么" aria-label="Permalink to &quot;1. 三条通道分别是什么&quot;">​</a></h3><p>板子上的固件可以经三条完全不同的链路进来：</p><table tabindex="0"><thead><tr><th>通道</th><th>载体</th><th>触发方式</th><th>代码位置</th></tr></thead><tbody><tr><td>串口</td><td>USART1（CH340 转 USB）</td><td>上位机脚本直接发字节</td><td><code>usart1</code> 驱动 + <code>iap.c</code></td></tr><tr><td>TCP</td><td>以太网 + lwIP</td><td><code>tools/send_iap_tcp.py</code> 连接 8888 端口</td><td><code>port/iap_tcp.c</code></td></tr><tr><td>TFTP</td><td>以太网 + UDP</td><td>串口输入 <code>update</code> 命令后从服务器拉取</td><td><code>Drivers/BSP/Ota/ota_tftp.c</code></td></tr></tbody></table><h3 id="_2-共用帧格式的两个好处" tabindex="-1">2. 共用帧格式的两个好处 <a class="header-anchor" href="#_2-共用帧格式的两个好处" aria-label="Permalink to &quot;2. 共用帧格式的两个好处&quot;">​</a></h3><p>（1）<strong>板侧只有一份校验与写 Flash 的逻辑</strong>。三条通道的字节最终都交给同一个状态机 <code>iap.c</code>，所以 CRC32、向量表、长度上限、写 Flash 与回读比对这些规则<strong>不会出现&quot;串口一套、网络一套&quot;的分歧</strong>。</p><p>（2）<strong>同一份固件产物可以走任意通道</strong>。<code>tools/pack_iap.py</code> 打出来的 <code>app.img</code> 既能喂串口脚本、也能喂 TCP 脚本、还能直接扔进 TFTP 服务器根目录，不需要为通道再打一次包。</p><p>这也是为什么 <a href="/scm-docs/sdoc/advanced-chapter/ethernet/126d628e13a5261051823e07.html">LV025</a> 里能说&quot;帧校验与写 Flash 全部复用 <code>iap.c</code>，本模块一行不重复实现&quot;。</p><h2 id="二、-iapbin01-帧格式" tabindex="-1">二、 IAPBIN01 帧格式 <a class="header-anchor" href="#二、-iapbin01-帧格式" aria-label="Permalink to &quot;二、 IAPBIN01 帧格式&quot;">​</a></h2><h3 id="_1-头部-16-字节" tabindex="-1">1. 头部 16 字节 <a class="header-anchor" href="#_1-头部-16-字节" aria-label="Permalink to &quot;1. 头部 16 字节&quot;">​</a></h3><p>帧格式定义在 <code>Drivers/BSP/Iap/iap.h</code> 的文件头注释里，与上位机 <code>tools/pack_iap.py</code> <strong>必须严格一致</strong>，任一侧改动都要同步另一侧：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>+---------------- 头部 16 字节 ----------------+</span></span>
<span class="line"><span>| 偏移 0   8B   魔数 &quot;IAPBIN01&quot;                |</span></span>
<span class="line"><span>| 偏移 8   4B   载荷长度 N   (小端 uint32)     |</span></span>
<span class="line"><span>| 偏移 12  4B   载荷 CRC32   (小端 uint32)     |</span></span>
<span class="line"><span>+---------------- 载荷 N 字节 ------------------+</span></span>
<span class="line"><span>| 偏移 16   N   原始 bin 字节                  |</span></span>
<span class="line"><span>+---------------- 尾部 8 字节 ------------------+</span></span>
<span class="line"><span>| 偏移 16+N 8B  魔数 &quot;IAPEOF01&quot;                |</span></span>
<span class="line"><span>+-----------------------------------------------+</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br></div></div><img src="`+i+`" alt="IAPBIN01 帧的头部、载荷与尾部结构"><h3 id="_2-载荷与尾部魔数" tabindex="-1">2. 载荷与尾部魔数 <a class="header-anchor" href="#_2-载荷与尾部魔数" aria-label="Permalink to &quot;2. 载荷与尾部魔数&quot;">​</a></h3><table tabindex="0"><thead><tr><th>字段</th><th>长度</th><th>说明</th></tr></thead><tbody><tr><td>魔数</td><td>8 字节</td><td><code>IAPBIN01</code>，逐字节扫描匹配</td></tr><tr><td>载荷长度 N</td><td>4 字节</td><td>小端，上限 <code>IAP_PAYLOAD_MAX</code> = 128 KB</td></tr><tr><td>载荷 CRC32</td><td>4 字节</td><td>小端，覆盖载荷 N 字节</td></tr><tr><td>载荷</td><td>N 字节</td><td>原始 bin，来自 <code>flash-app</code> 工程的编译产物</td></tr><tr><td>尾部魔数</td><td>8 字节</td><td><code>IAPEOF01</code>，用来确认&quot;这一帧真的收完了&quot;</td></tr></tbody></table><p>128 KB 这个上限不是随便定的：它与上位机 <code>pack_iap.py</code> 的 <code>APP_MAX_SIZE</code> 对齐，等于 APP 区（<code>0x08020000</code> ~ <code>0x08040000</code>）能容纳的最大 bin。<strong>它是溢出防线的硬上限</strong>——头部声明的长度一旦超过它就直接报错，绝不进入载荷接收阶段，也就不会出现&quot;按一个伪造的长度往 Flash 里猛写&quot;的情况。</p><h3 id="_3-版本号的设计" tabindex="-1">3. 版本号的设计 <a class="header-anchor" href="#_3-版本号的设计" aria-label="Permalink to &quot;3. 版本号的设计&quot;">​</a></h3><p>魔数的末两位是<strong>帧格式版本</strong>：</p><div class="language-c vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">c</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// Drivers/BSP/Iap/iap.h</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">#define</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> IAP_MAGIC_PREFIX</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">     &quot;IAPBIN&quot;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   /* 前 6 字节 */</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">#define</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> IAP_MAGIC_VERSION</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    &quot;01&quot;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">       /* 帧格式版本, 2 字节 */</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>这样设计的好处是：<strong>前缀匹配而版本不符时会单独报&quot;版本错误&quot;，而不是被当成&quot;没对齐&quot;从头继续扫描</strong>。升级协议时能一眼看出是版本问题，而不是在&quot;找不到帧头&quot;上白费功夫。</p><h2 id="三、-收帧状态机与错误码" tabindex="-1">三、 收帧状态机与错误码 <a class="header-anchor" href="#三、-收帧状态机与错误码" aria-label="Permalink to &quot;三、 收帧状态机与错误码&quot;">​</a></h2><h3 id="_1-四个阶段与四个事件" tabindex="-1">1. 四个阶段与四个事件 <a class="header-anchor" href="#_1-四个阶段与四个事件" aria-label="Permalink to &quot;1. 四个阶段与四个事件&quot;">​</a></h3><p>状态机由 <code>iap_rx_byte()</code> 逐字节推进，由 <code>iap_rx_poll()</code> 在主循环里推进超时与校验：</p><table tabindex="0"><thead><tr><th>阶段</th><th>做什么</th><th>产出事件</th></tr></thead><tbody><tr><td>扫描</td><td>逐字节比对魔数前缀与版本</td><td>匹配到帧头 → 进入收头部</td></tr><tr><td>收头部</td><td>读出长度与 CRC32，校验长度上限</td><td><code>IAP_EVT_HEADER</code></td></tr><tr><td>收载荷</td><td>逐字节写入载荷缓冲并累计长度</td><td>—</td></tr><tr><td>收尾部</td><td>比对 <code>IAPEOF01</code></td><td>收齐 → <code>IAP_EVT_FRAME_OK</code></td></tr></tbody></table><div class="language-c vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">c</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">typedef</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> enum</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    IAP_EVT_NONE </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   /* 无新进展 */</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    IAP_EVT_HEADER,</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">     /* 头部解析完成且长度合法, 载荷开始接收 */</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    IAP_EVT_FRAME_OK,</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   /* 整帧收齐, CRC32 校验通过 */</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    IAP_EVT_FRAME_ERR</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   /* 收帧失败, 原因见 iap_rx_last_error() */</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">} </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">iap_evt_t</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div><p>用&quot;事件&quot;而不是&quot;回调&quot;的写法有个实际好处：<strong>业务层可以在主循环里一次性处理结果</strong>，不必担心收帧过程与业务逻辑重入。</p><h3 id="_2-六种失败原因" tabindex="-1">2. 六种失败原因 <a class="header-anchor" href="#_2-六种失败原因" aria-label="Permalink to &quot;2. 六种失败原因&quot;">​</a></h3><div class="language-c vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">c</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">typedef</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> enum</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    IAP_ERR_NONE </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   /* 尚未失败过 */</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    IAP_ERR_VERSION,</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    /* 魔数前缀匹配但帧格式版本不符 */</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    IAP_ERR_TOO_LARGE,</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  /* 头部声明的长度非法或超过 IAP_PAYLOAD_MAX */</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    IAP_ERR_TRAILER,</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    /* 尾部魔数不匹配 */</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    IAP_ERR_CRC,</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">        /* CRC32 校验失败 */</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    IAP_ERR_TIMEOUT</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">     /* 收帧超时 */</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">} </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">iap_err_t</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br></div></div><p>对着下表就能判断&quot;是哪一侧的问题&quot;，这是这套错误码最大的价值：</p><table tabindex="0"><thead><tr><th>错误</th><th>大概率原因</th></tr></thead><tbody><tr><td><code>IAP_ERR_VERSION</code></td><td>上位机与新板子的帧版本不一致（升级时只更新了一侧）</td></tr><tr><td><code>IAP_ERR_TOO_LARGE</code></td><td>传的不是 APP 固件（比如误传了整片 Flash 的 bin）</td></tr><tr><td><code>IAP_ERR_TRAILER</code></td><td>传输中途被打断，字节数对不上</td></tr><tr><td><code>IAP_ERR_CRC</code></td><td>链路有误码，或 <code>app.img</code> 与板侧期望的内容不一致</td></tr><tr><td><code>IAP_ERR_TIMEOUT</code></td><td>PC 侧卡住（防火墙、杀软、脚本被挂起）</td></tr></tbody></table><h3 id="_3-超时重对齐" tabindex="-1">3. 超时重对齐 <a class="header-anchor" href="#_3-超时重对齐" aria-label="Permalink to &quot;3. 超时重对齐&quot;">​</a></h3><p>收帧中途允许的最大字节间隔是 <code>IAP_RX_TIMEOUT_MS = 3000</code>（3 秒），超过就判定超时并<strong>重新对齐</strong>。</p><p>这一步的必要性在于&quot;主机中途取消&quot;这个场景：如果 PC 侧传了一半就关掉连接，板子按字节数算还差一半，会<strong>永远停在半帧状态</strong>，后续任何一次正确的升级请求都被当成&quot;半帧的后续字节&quot;处理。超时重对齐让状态机能自己爬出这个坑。</p><h2 id="四、-载荷缓冲与-crc32-的时机" tabindex="-1">四、 载荷缓冲与 CRC32 的时机 <a class="header-anchor" href="#四、-载荷缓冲与-crc32-的时机" aria-label="Permalink to &quot;四、 载荷缓冲与 CRC32 的时机&quot;">​</a></h2><h3 id="_1-128-kb-载荷放在哪" tabindex="-1">1. 128 KB 载荷放在哪 <a class="header-anchor" href="#_1-128-kb-载荷放在哪" aria-label="Permalink to &quot;1. 128 KB 载荷放在哪&quot;">​</a></h3><p>这是一个必须先解决的硬约束：<strong>STM32F103ZET6 只有 64 KB 内部 SRAM，而载荷上限是 128 KB。</strong></p><p>所以载荷缓冲放在<strong>外部 SRAM</strong>（IS62WV51216，挂在 FSMC 的 NE3 上）。这也带来两个连带约束：</p><p>（1）访问外部 SRAM 与访问 DM9000 共用同一条 FSMC 总线，所以&quot;写索引 + 读数据&quot;这类操作要防并发，理由见 <a href="/scm-docs/sdoc/advanced-chapter/ethernet/126d628e13a516684ed019b4.html">LV001-以太网与DM9000硬件接口</a> 第五节。</p><p>（2）<strong><code>MX_FSMC_Init()</code> 必须先于任何网络与 IAP 操作执行</strong>，否则访问外部 SRAM 直接进 HardFault。</p><h3 id="_2-crc-为什么放在主循环算" tabindex="-1">2. CRC 为什么放在主循环算 <a class="header-anchor" href="#_2-crc-为什么放在主循环算" aria-label="Permalink to &quot;2. CRC 为什么放在主循环算&quot;">​</a></h3><p><code>iap_rx_byte()</code> 运行在<strong>串口接收中断上下文</strong>，它每字节只做两件事：一次 O(1) 的状态迁移、一次缓冲写入。<strong>不算 CRC、不打印。</strong></p><p>原因是算力账：128 KB 载荷用逐位实现的 CRC32 要跑一百多毫秒，放在中断里意味着这段时间内的所有后续字节都会被丢掉。</p><p>所以 CRC32 被挪到 <code>iap_rx_poll()</code>（主循环，建议 1 ms 一次）。这也是 <code>iap.h</code> 注释里那句&quot;必须在主循环里周期调用&quot;的由来，与 <a href="/scm-docs/sdoc/advanced-chapter/ethernet/126d628e13a51b6ce0b937cd.html">LV010-lwIP协议栈移植</a> 里&quot;回调里只做 O(1) 搬运&quot;是同一条原则。</p><h2 id="五、-三条通道的接入方式" tabindex="-1">五、 三条通道的接入方式 <a class="header-anchor" href="#五、-三条通道的接入方式" aria-label="Permalink to &quot;五、 三条通道的接入方式&quot;">​</a></h2><h3 id="_1-sink-回调的统一套路" tabindex="-1">1. sink 回调的统一套路 <a class="header-anchor" href="#_1-sink-回调的统一套路" aria-label="Permalink to &quot;1. sink 回调的统一套路&quot;">​</a></h3><p>三条通道的差别只在&quot;字节从哪来&quot;，接入方式完全一致——都实现成一个 sink 回调：</p><table tabindex="0"><thead><tr><th>通道</th><th>字节怎么到 <code>iap_rx_byte()</code></th><th>期间串口怎么办</th></tr></thead><tbody><tr><td>串口</td><td><code>usart1_set_rx_sink(iap_rx_byte)</code>，中断里直接喂</td><td>命令识别挂起</td></tr><tr><td>TCP</td><td><code>iap_tcp_recv()</code> 遍历 pbuf 链，逐字节喂</td><td>建连时 <code>usart1_set_rx_sink(0)</code> 摘掉</td></tr><tr><td>TFTP</td><td>UDP 收到块后经 sink 回调喂</td><td>传输期间摘掉串口消费器</td></tr></tbody></table><p>还有一处防呆设计：<strong>匹配到帧头的那一刻，状态机会调用 <code>usart1_cmd_set_enabled(0)</code> 挂起命令识别，回到扫描态时恢复。</strong> 因为二进制载荷里恰好凑出 <code>go</code>、<code>reboot</code> 这种命令字样的概率虽然低，但没必要赌——一旦真发生，就会在收帧途中触发一次芯片复位。</p><h3 id="_2-通道互斥的三个检查点" tabindex="-1">2. 通道互斥的三个检查点 <a class="header-anchor" href="#_2-通道互斥的三个检查点" aria-label="Permalink to &quot;2. 通道互斥的三个检查点&quot;">​</a></h3><table tabindex="0"><thead><tr><th>场景</th><th>检查点</th><th>行为</th></tr></thead><tbody><tr><td>已有 TCP 会话，又来一个连接</td><td><code>iap_tcp.c</code> accept 回调</td><td><code>tcp_abort</code> 新连接</td></tr><tr><td>TFTP 正在传输，来了 TCP 客户端</td><td>同上</td><td><code>tcp_abort</code>，避免两路字节混进同一状态机</td></tr><tr><td>TCP 会话中，输入 <code>update</code></td><td><code>ota_update.c</code> 的 <code>cmd_update()</code></td><td>打印拒绝原因并返回</td></tr></tbody></table><p>原则是<strong>在入口处拒绝，而不是在状态机里纠错</strong>：与其让两路字节混进来、收下半帧垃圾才报错，不如让第二次请求立刻失败。</p><h2 id="六、-上位机打包与向量表校验" tabindex="-1">六、 上位机打包与向量表校验 <a class="header-anchor" href="#六、-上位机打包与向量表校验" aria-label="Permalink to &quot;六、 上位机打包与向量表校验&quot;">​</a></h2><h3 id="_1-pack-iap-py-的两道校验" tabindex="-1">1. pack_iap.py 的两道校验 <a class="header-anchor" href="#_1-pack-iap-py-的两道校验" aria-label="Permalink to &quot;1. pack_iap.py 的两道校验&quot;">​</a></h3><p>上位机侧的发包与打包都在 <code>tools/</code> 下：</p><table tabindex="0"><thead><tr><th>脚本</th><th>作用</th></tr></thead><tbody><tr><td><code>pack_iap.py</code></td><td>把裸 bin 打成 <code>IAPBIN01</code> 帧（算 CRC32、加头尾魔数），可加 <code>-f</code> 做填充</td></tr><tr><td><code>send_iap_tcp.py</code></td><td>走 TCP 通道发帧，给裸 bin 时会自动调用打包逻辑</td></tr></tbody></table><p><code>pack_iap.py</code> 在打包前会<strong>先校验向量表</strong>：</p><p>（1）<strong>栈顶指针（MSP）必须落在内部 SRAM 范围</strong>。</p><p>（2）<strong>复位向量必须落在 APP 区且最低位为 1</strong>（置位表示 Thumb 状态）。</p><p>这两条在 PC 侧拦掉了大部分错误产物——比如把 Bootloader 自己的 bin 当成 APP 传、或者忘了改 APP 的链接地址。<strong>在 PC 侧花几十微秒能发现的问题，等板子写完 Flash 再报错就要多花几十秒</strong>，这是很划算的一步。</p><h3 id="_2-与板侧校验的配合" tabindex="-1">2. 与板侧校验的配合 <a class="header-anchor" href="#_2-与板侧校验的配合" aria-label="Permalink to &quot;2. 与板侧校验的配合&quot;">​</a></h3><p>板侧在收完帧之后还有三道校验，两侧一起构成完整的防线：</p><table tabindex="0"><thead><tr><th>位置</th><th>校验内容</th></tr></thead><tbody><tr><td>PC 侧打包时</td><td>魔数版本、载荷长度上限（<code>APP_MAX_SIZE</code>）、向量表两条</td></tr><tr><td>板侧收帧时</td><td>头部长度是否超 <code>IAP_PAYLOAD_MAX</code>、尾部魔数、载荷 CRC32</td></tr><tr><td>板侧写 Flash 后</td><td>写完后回读比对（对应 <code>FLASH OK</code> 回执）</td></tr></tbody></table><p>三道校验分别拦&quot;打错包&quot;&quot;传错行&quot;&quot;写错位&quot;三类问题，缺一不可。</p><h2 id="七、-小结与参考资料" tabindex="-1">七、 小结与参考资料 <a class="header-anchor" href="#七、-小结与参考资料" aria-label="Permalink to &quot;七、 小结与参考资料&quot;">​</a></h2><h3 id="_1-本篇小结" tabindex="-1">1. 本篇小结 <a class="header-anchor" href="#_1-本篇小结" aria-label="Permalink to &quot;1. 本篇小结&quot;">​</a></h3><ul><li>串口、TCP、TFTP 三条通道共用一套帧格式与同一个状态机，好处是校验规则统一、固件产物可复用。</li><li>帧结构是&quot;16 字节头（8B 魔数 + 4B 长度 + 4B CRC32）+ N 字节载荷 + 8B 尾部魔数&quot;，长度上限 128 KB，与 APP 区大小对齐。</li><li>魔数末两位是版本号，版本不符会单独报 <code>IAP_ERR_VERSION</code>，而不是被当成&quot;没对齐&quot;。</li><li>状态机逐字节推进、以事件形式上报；六种错误码可以直接定位问题出在哪一侧。</li><li>收帧中途超过 3 秒（<code>IAP_RX_TIMEOUT_MS</code>）就超时重对齐，避免永远停在半帧状态。</li><li>128 KB 载荷放外部 SRAM；CRC32 放在主循环算，绝不能放在中断里。</li><li>三条通道统一用 sink 回调接入，入口处互相拒绝；匹配到帧头时还要挂起命令识别。</li><li>上位机的向量表校验与板侧的长度/魔数/CRC 校验、写后回读，共同构成三道防线。</li></ul><h3 id="_2-参考资料" tabindex="-1">2. 参考资料 <a class="header-anchor" href="#_2-参考资料" aria-label="Permalink to &quot;2. 参考资料&quot;">​</a></h3><ul><li>帧格式与状态机：<a href="https://cnb.cool/smk.k/Microcontroller/bootloader/-/blob/main/atk-f103/Drivers/BSP/Iap/iap.h" target="_blank" rel="noreferrer"><code>iap.h</code></a>、<a href="https://cnb.cool/smk.k/Microcontroller/bootloader/-/blob/main/atk-f103/Drivers/BSP/Iap/iap.c" target="_blank" rel="noreferrer"><code>iap.c</code></a></li><li>业务层与命令：<a href="https://cnb.cool/smk.k/Microcontroller/bootloader/-/blob/main/atk-f103/Drivers/BSP/Iap/iap_service.c" target="_blank" rel="noreferrer"><code>iap_service.c</code></a></li><li>通道实现：<a href="https://cnb.cool/smk.k/Microcontroller/bootloader/-/blob/main/atk-f103/Components/lwip-2.1.3/port/iap_tcp.c" target="_blank" rel="noreferrer"><code>iap_tcp.c</code></a>、<a href="https://cnb.cool/smk.k/Microcontroller/bootloader/-/blob/main/atk-f103/Drivers/BSP/Ota/ota_tftp.c" target="_blank" rel="noreferrer"><code>ota_tftp.c</code></a></li><li>上位机：<a href="https://cnb.cool/smk.k/Microcontroller/bootloader/-/blob/main/tools/pack_iap.py" target="_blank" rel="noreferrer"><code>tools/pack_iap.py</code></a>、<a href="https://cnb.cool/smk.k/Microcontroller/bootloader/-/blob/main/tools/send_iap_tcp.py" target="_blank" rel="noreferrer"><code>tools/send_iap_tcp.py</code></a></li></ul><hr><p><em>本文档由 markdowncli 技能辅助生成</em></p>`,72)])])}const u=t(d,[["render",r]]);export{k as __pageData,u as default};
